    height: var(--ew-structure-slider-track-height, 6px);
    border-radius: var(--ew-structure-slider-track-radius, 999px);
  }
  .ew-slider__control:focus-visible { outline: 2px solid var(--ew-color-field-focus); outline-offset: 2px; }
