  .ew-slider[data-size="md"] { --ew-spec-size: md; }
  .ew-slider[data-size="lg"] { --ew-spec-size: lg; }
  .ew-slider:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-slider, .ew-slider *, .ew-slider *::before, .ew-slider *::after {
      transition: none !important;
      animation: none !important;
